import os
import subprocess
import sys

def run_command(cmd):
    try:
        res = subprocess.run(cmd, capture_output=True, text=True, timeout=30)
        return res.returncode, res.stdout, res.stderr
    except Exception as e:
        return -1, "", str(e)

files_found = []
for root, dirs, files in os.walk('.'):
    for f in files:
        if any(x in root for x in ['.git', '__pycache__', 'node_modules', 'venv']):
            continue
        files_found.append(os.path.join(root, f))

print('All files in workspace:')
for f in files_found:
    print(f'- {f}')

target_files = [f for f in files_found if any(k in f.lower() for k in ['cancel', 'import', 'test'])]
print('\nTarget files:')
for f in target_files:
    print(f'- {f}')
    if f.endswith('.py'):
        print(f'--- Content of {f} ---')
        try:
            with open(f, 'r') as file_obj:
                print(file_obj.read())
        except Exception as e:
            print(f'Error reading {f}: {e}')

print('\n--- Running Tests ---')
for f in target_files:
    if f.endswith('.py') and 'test' in f.lower():
        print(f'\nRunning pytest on {f}:')
        code, stdout, stderr = run_command([sys.executable, '-m', 'pytest', f])
        print(f'Exit Code: {code}')
        print(f'STDOUT:\n{stdout}')
        print(f'STDERR:\n{stderr}')

        if code != 0:
            print(f'\nRunning python directly on {f}:')
            code, stdout, stderr = run_command([sys.executable, f])
            print(f'Exit Code: {code}')
            print(f'STDOUT:\n{stdout}')
            print(f'STDERR:\n{stderr}')
